"""gRPC KV store server for string keys with integer values."""

from concurrent import futures

import grpc

import kv_store_pb2
import kv_store_pb2_grpc

PORT = 5328


class Server(kv_store_pb2_grpc.KVStoreServicer):
    """Implements the KVStore service backed by an in-memory dict."""

    def __init__(self):
        self.store = {}

    def GetVal(self, request, context):
        # Missing keys are treated as having the default value 0.
        return kv_store_pb2.GetValResponse(val=self.store.get(request.key, 0))

    def SetVal(self, request, context):
        self.store[request.key] = request.value
        return kv_store_pb2.SetValResponse(val=self.store[request.key])


def serve():
    grpc_server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), grpc_server)
    grpc_server.add_insecure_port(f"[::]:{PORT}")
    grpc_server.start()
    print(f"KVStore server listening on port {PORT}", flush=True)
    grpc_server.wait_for_termination()


if __name__ == "__main__":
    serve()

